import {
  type Directive,
  type ParserOptions,
  type Program,
  type PropertyKey,
  parseSync,
  rawTransferSupported,
  type Span,
  type Statement
} from 'oxc-parser';
import { PrismaJsonTypesGeneratorError } from './error';

/**
 * Parses a file generated by prisma. The file extension picks the syntax, `.d.ts` files
 * allow declarations without initializers, which are errors in `.ts` files.
 */
export function parseSource(filepath: string, content: string): Program {
  const { program, errors } = parse(filepath, content);

  // Replacing types in a file that did not fully parse could silently produce broken output
  if (errors.length) {
    throw new PrismaJsonTypesGeneratorError('Could not parse generated file', {
      filepath,
      errors: errors.map((error) => error.message)
    });
  }

  return program;
}

function parse(filepath: string, content: string) {
  // Raw transfer reads the AST from Rust memory instead of JSON, 2 to 5 times faster on
  // large clients. It is experimental and reserves a 6 GiB virtual buffer that restricted
  // environments may refuse, so any failure falls back to the JSON path.
  if (rawTransferSupported()) {
    try {
      return parseSync(filepath, content, {
        sourceType: 'module',
        experimentalRawTransfer: true
      } as ParserOptions);
    } catch {}
  }

  return parseSync(filepath, content, { sourceType: 'module' });
}

/** ESTree wraps `export type X` and `export namespace X` in an `ExportNamedDeclaration`. */
export function unwrapExport(statement: Directive | Statement) {
  return statement.type === 'ExportNamedDeclaration'
    ? (statement.declaration ?? undefined)
    : statement;
}

/** Source text of a node, without leading trivia. */
export function getText(content: string, node: Span) {
  return content.slice(node.start, node.end);
}

/** Name of a non-computed identifier key, like `field` in `{ field: string }`. */
export function getIdentifierName(key: PropertyKey, computed: boolean) {
  return !computed && key.type === 'Identifier' ? key.name : undefined;
}
